void __fastcall SOUNDHDR_LoadSoundFile(int32_t nSoundId, int32_t bForceSync, int32_t bRespectRecency) {
    D2PoolManagerStrc* pMpqMgr;
    void* pSoundData;
    D2SoundsTxt* pSound;
    char szPath[80];
    D2MPQFileStrc* pMpqFile;
    int32_t* pSoundDataBytes;
    char* szSourceFile;
    if (!pTxtSounds || nSoundId < 0 || nTxtSoundsSize <= nSoundId) {
      pSound = 0;
    } else {
      pSound = pTxtSounds + nSoundId;
    }

    int nNowVolume = gnCurrentGameAudioVolume;
    if (pSound->bFileNotFound) {
      return;
    }

    int nLoadStateOrBytes = pSound->nLoadState;
    if (nLoadStateOrBytes == 2) {
      return;
    }

    int32_t bForceSyncLocal = bForceSync;
    if (nLoadStateOrBytes == 1) {
      if (!bForceSync) {
        return;
      }
      if (true && bForceSync) {
        SOUNDHDR_CompleteAsyncLoad((int32_t)pSound);
        return;
      }
    }
    if (nLoadStateOrBytes) {
      return;
    }

    SOUNDHDR_BuildSoundPath(nSoundId, (uint32_t*)szPath);
    int32_t nResult = Fog::Source::SFile::ARCHIVE_OpenD2FileWrap(szPath, &pMpqFile);
    if (!nResult) {
      pSound->bFileNotFound = 1;
      return;
    }

    DWORD nFileSize = Fog::Source::SFile::ERRORMANAGER_FGetFileSize(pMpqFile, (LPDWORD)0x0);
    Fog::Source::SFile::ERRORMANAGER_FCloseFile(pMpqFile);
    if (gnSoundBufferMaxBytes < gnSoundBufferBytesLoaded + nFileSize) {
      BOOL BVar1;
      BVar1 = SOUNDHDR_EvictLeastRecentlyUsed(gnSoundBufferBytesLoaded - gnSoundBufferMaxBytes + nFileSize, bForceSyncLocal, bRespectRecency);
      if (!BVar1) {
        gnSoundEvictedAudioVolume = nNowVolume;
        return;
      }
    }
    if (bForceSyncLocal) {
      nResult = 0x301;
      szSourceFile = ".\\Sound\\SoundHdr.cpp";
      pSoundDataBytes = &pSound->nSoundDataBytes;
      pMpqMgr = D2Win::Src::D2WinArchive::ReturnZero();
      pSoundData = Fog::Archive::D2FILE_AllocAndLoadD2File(pMpqMgr, szPath, (size_t*)pSoundDataBytes, szSourceFile, nResult);
      pSound->pSoundDataBuffer = pSoundData;
      if (pSoundData) {
        nLoadStateOrBytes = pSound->nSoundDataBytes;
        if (nLoadStateOrBytes) {
          gnSoundBufferBytesLoaded += nLoadStateOrBytes;
          SOUNDHDR_UpdateLRUTimestamp(nSoundId);
          pSound->nLoadState = 2;
          GAME::Sound::SOUND_ParseStreamWavHeader((int32_t)pSound);
          return;
        }
      }

      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x302);
      exit(-1);
    }

    D2AsyncData_Line0x128* pAsyncData = Fog::Src::AsyncData::STRUCT_AllocAsyncData_Line0x128(nullptr, szPath, 1, 0, -1, nullptr, nullptr, -2, ".\\Sound\\SoundHdr.cpp", 0x31b);
    pSound->pAsyncData = pAsyncData;
    if (!pAsyncData) {
      return;
    }

    size_t sVar2 = Fog::Src::AsyncData::ASYNCDATA_GetReadSize(pAsyncData);
    gnSoundBufferBytesLoaded += sVar2;
    pSound->nSoundDataBytes = sVar2;
    SOUNDHDR_UpdateLRUTimestamp(nSoundId);
    gnSoundAsyncLoadCount++;
    pSound->nLoadState = 1;
}

