void __stdcall DRAW_AfterDraw() {
    BOOL bSoundInitialized = GAME::Sound::SOUND_IsInitialized();
    if (!bSoundInitialized) {
      return;
    }

    SOUND_UpdateEnvironmentAmbience(gnCurrentGameAudioVolume);
    GAME::Wall2::WALL2_UpdateAmbientMusic(gnCurrentGameAudioVolume);
    SOUNDHDR_ProcessAsyncLoads(gnCurrentGameAudioVolume);
    SOUND_UpdateAllChannels(gnCurrentGameAudioVolume);
    GAME::Sound::SOUND_UpdateNonLoopingStreams();
    gnCurrentGameAudioVolume++;
    /* DWORD dwMilliseconds for Sleep */ Sleep(0);
}

